UPDATE talk_parts SET speaker = 'Isla', say = '["Hi! We are the Rooted Warriors from Flagstaff, Arizona.","(Everyone says their own name, down the line.)","Imagine driving on I-17 at night when an elk steps onto the road. So we built a wildlife camera that shows where animals really cross."]' WHERE id = 1 AND talk = 'ip';
UPDATE talk_parts SET speaker = 'Nolan', say = '["Here is our problem. Nate Reagan from Arizona Game and Fish told us I-17 has about 300 animal strikes a year. That is almost one crash every single day.","A new 24-million-dollar wildlife bridge at Willard Springs should cut those crashes by 90 percent.","But Game and Fish might only put one camera on it, and they can''t share their data with us. So how will anyone know if animals really use it?"]' WHERE id = 2 AND talk = 'ip';
